#!/usr/bin/env python3
"""Generate deterministic Java rig code from the checked-in cuboid specification."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / 'src/client/java/dev/sigmachan/companions/client/CompanionModelData.java'
SPEC = json.loads((ROOT / 'tools/model_specs.json').read_text())


def f(value):
    return f'{value:g}f'


def vec(values):
    return ', '.join(map(f, values))


def generate():
    lines = ['package dev.sigmachan.companions.client;', '',
             '// Generated by tools/generate_models.py; edit tools/model_specs.json instead.',
             'import net.minecraft.client.model.*;', 'import java.util.LinkedHashMap;', 'import java.util.Map;', '',
             'public final class CompanionModelData {', '    private CompanionModelData() {}',
             '    public static TexturedModelData build() {',
             '        ModelData data = new ModelData();', '        ModelPartData root = data.getRoot();',
             '        Map<String, ModelPartData> parts = new LinkedHashMap<>();',
             '        buildCommon(root, parts);']
    for name in SPEC['profiles']:
        lines += [f'        build{name.capitalize()}(parts, "{name}_");']
    lines += ['        return TexturedModelData.of(data, 256, 256);', '    }']
    groups = [('Common', SPEC['common'])] + [(name.capitalize(), parts) for name, parts in SPEC['profiles'].items()]
    for name, parts in groups:
        lines += [f'    private static void build{name}({"ModelPartData root, " if name == "Common" else ""}Map<String, ModelPartData> parts{", String prefix" if name != "Common" else ""}) {{']
        for part in parts:
            key = part['name'] if name == 'Common' else part['name']
            parent = 'root' if part['parent'] is None else f'parts.get("{part["parent"]}")'
            put_key = f'"{key}"' if name == 'Common' else f'prefix + "{key}"'
            child_name = f'"{key}"' if name == 'Common' else f'prefix + "{key}"'
            u, v = part['uv']; w, h, d = part['size']
            lines += [f'        parts.put({put_key}, {parent}.addChild({child_name}, '
                      f'new ModelPartBuilder().uv({u}, {v}).cuboid({vec(part["offset"])}, {w}, {h}, {d}), '
                      f'ModelTransform.pivot({vec(part["pivot"])})));']
        lines += ['    }']
    lines += ['    public static Map<String, ModelPart> bind(ModelPart root) {',
              '        Map<String, ModelPart> parts = new LinkedHashMap<>();',
              '        Map<String, String> parents = new LinkedHashMap<>();']
    all_parts = SPEC['common'] + [p for group in SPEC['profiles'].values() for p in group]
    seen = set()
    for group_name, group in [('common', SPEC['common'])] + list(SPEC['profiles'].items()):
        for part in group:
            key = part['name'] if group_name == 'common' else group_name + '_' + part['name']
            if key in seen: continue
            seen.add(key)
            lines += [f'        parents.put("{key}", {json.dumps(part["parent"])});']
    lines += ['        for (var entry : parents.entrySet()) {',
              '            ModelPart part = root;', '            String parent = entry.getValue();',
              '            if (parent != null) part = parts.get(parent);',
              '            parts.put(entry.getKey(), part.getChild(entry.getKey()));', '        }',
              '        return parts;', '    }', '    public static void reset(Map<String, ModelPart> parts) {']
    seen = set()
    for group_name, group in [('common', SPEC['common'])] + list(SPEC['profiles'].items()):
        for part in group:
            key = part['name'] if group_name == 'common' else group_name + '_' + part['name']
            if key in seen: continue
            seen.add(key)
            lines += [f'        reset(parts, "{key}", {vec(part["pivot"])});']
    lines += ['    }', '    private static void reset(Map<String, ModelPart> parts, String name, float x, float y, float z) {',
              '        ModelPart part = parts.get(name);', '        if (part == null) return;',
              '        part.resetTransform(); part.pivotX = x; part.pivotY = y; part.pivotZ = z;',
              '    }', '}']
    return '\n'.join(lines) + '\n'


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    result = generate()
    if args.check:
        assert TARGET.read_text() == result, 'Generated model code is stale; run tools/generate_models.py'
        print('Generated model code matches specification.')
    else:
        TARGET.write_text(result)
        print(f'Generated {TARGET.relative_to(ROOT)}')